export function normalizePassRate(input: number | null | undefined): number | null {
  if (input == null) return null;
  if (!Number.isFinite(input)) {
    throw new Error(`Invalid pass_rate: ${input} — must be a finite number`);
  }
  const passRate = input > 1 ? input / 100 : input;
  if (passRate < 0 || passRate > 1) {
    throw new Error(`Invalid pass_rate: ${input} — out of range (must be 0-1 fraction or 0-100 percent)`);
  }
  return passRate;
}

function validate(value: string | undefined, allowed: string[], field: string): void {
  if (value && !allowed.includes(value)) {
    // Stage C humanization: show both the bad value and the allowed list
    // so the operator doesn't have to grep the source to find the enum.
    throw new Error(`Invalid ${field}: "${value}". Must be one of: ${allowed.join(', ')}`);
  }
}

export function getExceptions(repoId: number | bigint): Record<string, any>[] {
  const db = getDb();
  return db.prepare(`
    SELECT ae.*, ac.title AS control_title
    FROM audit_exceptions ae
    LEFT JOIN audit_controls ac ON ac.id = ae.control_id
    WHERE ae.repo_id = ?
    ORDER BY ae.created_at DESC
  `).all(repoId) as Record<string, any>[];
}

function config(): ReturnType<typeof resolveConfig> {
  if (!_configCache) _configCache = resolveConfig();
  return _configCache;
}

function parsePositiveInt(value: string, label: string): number {
  const trimmed = value.trim();
  const n = Number.parseInt(trimmed, 10);
  if (!Number.isFinite(n) || n < 1 || String(n) !== trimmed) {
    console.error(`Invalid ${label}: ${value}`);
    console.error(`Expected a positive integer (e.g., --limit 10).`);
    process.exit(2);
  }
  return n;
}

function emit<T>(data: T, json: boolean, renderText: (data: T) => void): void {
  if (json) {
    console.log(JSON.stringify(data, null, 2));
  } else {
    renderText(data);
  }
}

function notFoundJson(slug: string, json: boolean): boolean {
  if (json) {
    console.log(JSON.stringify({ error: 'not_found', slug }, null, 2));
    return true;
  }
  return false;
}

function validateSlug(slug: string, cmdHint: string): void {
  if (!SLUG_RE.test(slug)) {
    console.error(`Error: invalid slug "${slug}".`);
    console.error(`Expected: owner/name (e.g., mcp-tool-shop-org/repo-knowledge).`);
    console.error(`Example: rk ${cmdHint} mcp-tool-shop-org/repo-knowledge`);
    process.exit(2);
  }
}

function resolveRigId(explicit?: string): string {
  if (explicit && explicit.trim()) return explicit.trim();
  const envId = process.env.RK_RIG_ID;
  if (envId && envId.trim()) return envId.trim();
  const host = hostname();
  if (host && host.trim()) return host.trim();
  return 'unknown';
}

function getAllReposForVerify(): Array<{ id: number; slug: string; local_path: string | null }> {
  const db = getDb();
  return db.prepare(
    'SELECT id, slug, local_path FROM repos ORDER BY owner, name'
  ).all() as Array<{ id: number; slug: string; local_path: string | null }>;
}

