function isTruthyEnv(value: string | undefined): boolean {
  if (!value) return false;
  const v = value.trim().toLowerCase();
  if (v === "" || v === "0" || v === "false" || v === "no" || v === "off") {
    return false;
  }
  return true;
}

function fail(msg: string): never {
  process.stderr.write(`rig-bridge: ${msg}\n`);
  process.exitCode = 1;
  throw new BridgeReportedError();
}

function readGitConfigValue(root: string, key: string): string | null {
  const r = runGit(["config", "--get", key], root);
  if (r.status !== 0) return null;
  const v = r.stdout.trim();
  return v.length > 0 ? v : null;
}

function relayFilename(nonce: string): string {
  // The nonce shape from generateNonce is "<10-ts>-<10-rnd>". Take
  // the timestamp prefix as the filename ordinal; if a hypothetical
  // future ULID library produces a different shape, fall back to the
  // first 10 chars without splitting.
  const prefix = nonce.includes("-") ? nonce.split("-")[0] : nonce.slice(0, 10);
  return `RELAY-${prefix}.md`;
}

function flatten(values: string[]): string[] {
  return values
    .flatMap((v) => v.split(","))
    .map((s) => s.trim())
    .filter((s) => s.length > 0);
}

function chooseFilename(threadDir: string, type: MessageType): string {
  const bare = `${type}.md`;
  if (!existsSync(join(threadDir, bare))) return bare;
  let n = 2;
  while (n < 1000) {
    const cand = `${type}-${n}.md`;
    if (!existsSync(join(threadDir, cand))) return cand;
    n++;
  }
  throw new Error(`exhausted ordinal range for ${type} in ${threadDir}`);
}

function shouldUseColor(noColor: boolean | undefined, json: boolean): boolean {
  if (json) return false;
  if (noColor) return false;
  if (process.env.NO_COLOR !== undefined) return false;
  // process.stdout.isTTY is the standard Node check.
  return Boolean(process.stdout.isTTY);
}

function readDirtyFiles(root: string): string[] {
  const r = runGit(["status", "--porcelain"], root);
  if (r.status !== 0) return [];
  return r.stdout
    .split("\n")
    .map((line) => line.trim())
    .filter((line) => line.length > 0);
}

function shouldPage(lineCount: number, json: boolean): boolean {
  if (json) return false;
  if (process.env.RIG_BRIDGE_NO_PAGER === "1") return false;
  if (!process.stdout.isTTY) return false;
  const rows = process.stdout.rows;
  if (typeof rows !== "number" || rows <= 0) return false;
